LearnResult job = sai.learn().create(List.of(), new LearnOptions()
    .taskTemplate("Open {{newsSite}}, find all {{topic}} news published today, write their headlines into Notepad, one per line, and save the file as {{fileName}}")
    .inputs(Map.of("newsSite", "TechCrunch", "topic", "AI", "fileName", "techcrunch_headlines.txt"))
    .machine(pc)
    .criteria("techcrunch_headlines.txt is saved and holds, one per line, the headlines of the AI articles TechCrunch published today")
    .maxIterations(3) // up to 3 code versions; 0 (the default) only writes the code
    .rollouts(3) // each version must pass 3 runs in a row
    .reset(Map.of("code", """
        for (const t of await machine.browser.listTabs()) await machine.browser.closeTab(t.tabId)
        for (const w of await machine.getWindow("Notepad")) await w.close()"""))
    .continueWithAgent(true)); // after a failed run, the agent finishes the task and the repair learns from it
LearnResult done = sai.learn().waitFor(job); // can take an hour; pass a timeout to stop waiting
System.out.println(done.status() + " " + done.stopReason() + " " + done.testResult());
System.out.println(done.code()); // the latest version
for (LearnIteration it : done.iterations()) {
  System.out.println(it.index() + " " + it.changes() + " " + it.rollouts().stream().map(LearnRollout::verdict).toList());
}

LearnRun run = sai.learn().rollout(job, 1, 1); // what one run returned and logged, and its judgement
sai.learn().cancel(job); // stops at once and keeps the last complete results

